/**
 * Ícones Solar (estilo Outline), extraídos de @iconify-json/solar em build-time —
 * sem dependência de runtime (nenhuma lib de ícones é instalada no projeto).
 * Cada componente é um wrapper fino em cima do SVG original da Solar
 * (https://icones.js.org/collection/solar), usando currentColor para herdar
 * a cor do texto/tema automaticamente.
 */
import type { SVGProps } from "react";

export interface IconProps extends SVGProps<SVGSVGElement> {
  size?: number | string;
}

function makeIcon(body: string) {
  return function IconComponent({ size = 20, ...props }: IconProps) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        focusable="false"
        {...props}
        dangerouslySetInnerHTML={{ __html: body }}
      />
    );
  };
}

